// Prüfungsnahe Rechenaufgaben, Teil 4 (Technik): Struktur und Teilaufgaben wie in den IHK-Prüfungen, eigene Zahlen und Firmen
CALC.push(
/* ───── Wirkungsgrad eines Dieselmotors mit Riementrieb und Hydraulikpumpe (F2024 T3a) ───── */
{id:'c_diesel',qs:'BT',title:'Wirkungsgrad eines Dieselmotors: Frästrommel (Riementrieb) und Hydraulikpumpe',gen(){
  let t;for(let k=0;k<300;k++){const V=R(150,230,5),n=R(1800,2200,100),F=R(40,60,1),d=R(1000,1400,50),er=R(88,94,1),i=R(10,14,1),Qv=R(280,400,10),p=R(220,300,10),ep=R(80,90,1);
    const ntr=n/i/60,Ptr=F*1000*Math.PI*d/1000*ntr/1000,Pr=Ptr/(er/100),Ph=Qv*p/600,Pp=Ph/(ep/100),Pab=Pr+Pp,Pzu=V*0.83*42000/3600,eta=Pab/Pzu*100;
    if(eta>32&&eta<46){t={V,n,F,d,er,i,Qv,p,ep,ntr,Ptr,Pr,Ph,Pp,Pab,Pzu,eta};break}}
  const {V,n,F,d,er,i,Qv,p,ep,ntr,Ptr,Pr,Ph,Pp,Pab,Pzu,eta}=t;
  const ans=[{l:'zugeführte Leistung (Diesel)',v:Pzu,u:'kW',tol:0.004},{l:'Drehzahl der Frästrommel',v:ntr*60,u:'min⁻¹',tol:0.004},{l:'Leistung an der Frästrommel',v:Ptr,u:'kW',tol:0.005},{l:'Leistung am Riementrieb (Eingang)',v:Pr,u:'kW',tol:0.005},{l:'hydraulische Leistung der Pumpe',v:Ph,u:'kW',tol:0.005},{l:'Antriebsleistung der Pumpe',v:Pp,u:'kW',tol:0.005},{l:'vom Motor abgegebene Leistung',v:Pab,u:'kW',tol:0.005},{l:'Wirkungsgrad des Dieselmotors',v:eta,u:'%',tol:0.006}];
  return {text:`Eine Straßenfräse der Rauch Baumaschinen GmbH wird von einem Dieselmotor angetrieben. Er treibt über einen Keilriementrieb die Frästrommel und die Hydraulikpumpe für Fahr- und Verstellbewegungen an. Berechnen Sie den Wirkungsgrad des Dieselmotors bei Volllast, wenn er sowohl die Frästrommel als auch die Hydraulikpumpe mit den genannten Werten antreibt. Dichte und Heizwert von Diesel entnehmen Sie dem Tabellenbuch (ρ = 0,83 kg/dm³, Hu = 42.000 kJ/kg). Bezugsgröße: 1 Stunde.`,
  given:[['Dieselverbrauch',V+' L/h'],['Drehzahl Dieselmotor',f(n,0)+' min⁻¹'],['Kraft an der Frästrommel',F+' kN'],['Frästrommeldurchmesser',f(d,0)+' mm'],['Wirkungsgrad Keilriementrieb',er+' %'],['Gesamtübersetzung Keilriementrieb',i],['Volumenstrom Hydraulikpumpe',Qv+' L/min'],['Druck Hydraulikpumpe',p+' bar'],['Wirkungsgrad Hydraulikpumpe',ep+' %'],['Diesel (Tabellenbuch)','ρ = 0,83 kg/dm³ · Hu = 42.000 kJ/kg']],ans,
  steps:[{h:'Zugeführte Energie je Stunde'},{l:'W zu',f:['V · ρ · Hu',`${V} dm³ · 0,83 kg/dm³ · 42.000 kJ/kg`,f(V*0.83*42000,0)+' kJ  =  '+f(Pzu)+' kW']},
    {h:'Frästrommel'},{l:'n Trommel',f:[Q('n Motor','i'),Q(f(n,0)+' min⁻¹',i),f(ntr*60)+' min⁻¹ = '+f(ntr,3)+' s⁻¹']},{l:'P Trommel',f:['F · π · d · n',`${F*1000} N · π · ${f(d/1000,2)} m · ${f(ntr,3)} s⁻¹`,f(Ptr)+' kW']},{l:'P Riemen zu',f:[Q('P ab','η'),Q(f(Ptr)+' kW',f(er/100,2)),f(Pr)+' kW']},
    {h:'Hydraulikpumpe'},{l:'P hydraulisch',f:['Q · p : 600 (L/min · bar → kW)',Q(`${Qv} · ${p}`,'600'),f(Ph)+' kW']},{l:'P Pumpe zu',f:[Q('P ab','η'),Q(f(Ph)+' kW',f(ep/100,2)),f(Pp)+' kW']},
    {h:'Motor'},{l:'P ab',f:['P Riemen + P Pumpe',`${f(Pr)} + ${f(Pp)}`,f(Pab)+' kW']},{l:'η Motor',f:[Q('P ab','P zu'),Q(f(Pab),f(Pzu)),f(eta)+' %']}],
  tip:'Von hinten nach vorn rechnen: Nutzleistung → durch jeden Wirkungsgrad teilen → Summe der Teilleistungen am Motor → durch die zugeführte Brennstoffleistung teilen.'};}},

/* ───── Strömungsgeschwindigkeit in der Saugleitung (F2024 T3b) ───── */
{id:'c_stroemung',qs:'BT',title:'Strömungsgeschwindigkeit im Rohr prüfen (Rohr aus Normbezeichnung)',gen(){
  const da=pick([38,42,48,50,60]),s=pick([4,5,6,8]),di=da-2*s,A=Math.PI*di*di/4/100,Qv=R(150,420,10),vm=pick([0.8,1.0,1.2,1.5]);
  const v=Qv*1000/60/A/100,ok=v<=vm;
  const ans=[{l:'Innendurchmesser',v:di,u:'mm',tol:0.0001},{l:'Durchflussquerschnitt',v:A,u:'cm²',tol:0.005},{l:'Volumenstrom',v:Qv*1000/60,u:'cm³/s',tol:0.004},{l:'Strömungsgeschwindigkeit',v:v,u:'m/s',tol:0.005},{l:'Grenzwert eingehalten? (1 = ja, 0 = nein)',v:ok?1:0,u:'',tol:0.0001,abs:0.01}];
  return {text:`Die Hydraulikpumpe einer Maschine der Paulsen Hydraulik GmbH fördert ${Qv} L/min und wird über ein Präzisionsstahlrohr ${da} × ${s} (Außendurchmesser × Wanddicke in mm) aus dem Tank mit Öl versorgt. Überprüfen Sie rechnerisch, ob die maximal zulässige Strömungsgeschwindigkeit von ${f(vm,1)} m/s in der Versorgungsleitung eingehalten wird.`,
  given:[['Volumenstrom',Qv+' L/min'],['Rohr (Außen-Ø × Wanddicke)',`${da} × ${s} mm`],['zulässige Geschwindigkeit',f(vm,1)+' m/s']],ans,
  steps:[{l:'Innendurchmesser',f:['d_i = d_a − 2 · s',`${da} − 2 · ${s}`,di+' mm']},{l:'Querschnitt',f:['A = π · d_i² : 4',`π · ${f(di/10,1)}² cm² : 4`,f(A)+' cm²']},{l:'Volumenstrom',f:[`${Qv} L/min = ${Qv} dm³/min`,`${f(Qv*1000/60)} cm³/s`]},{l:'v',f:[Q('Q','A'),Q(f(Qv*1000/60)+' cm³/s',f(A)+' cm²'),f(v*100)+' cm/s = '+f(v)+' m/s']},{t:ok?`${f(v)} m/s ≤ ${f(vm,1)} m/s → Vorgabe eingehalten.`:`${f(v)} m/s > ${f(vm,1)} m/s → Vorgabe überschritten; ein größerer Rohrquerschnitt ist nötig.`}],
  tip:'Rohrbezeichnung: Außendurchmesser × Wanddicke. Der Innendurchmesser ergibt sich durch Abzug der doppelten Wanddicke.'};}},

/* ───── Gesamtförderhöhe einer Kühlmittelpumpe (F2025 T3b) ───── */
{id:'c_foerderhoehe',qs:'BT',title:'Gesamtförderhöhe einer Pumpe: Rohrreibung, Armaturen, Werkzeugdruck, geodätische Höhe',gen(){
  const da=pick([48.3,54,60,63.5]),s=pick([4,5,6]),di=Math.round((da-2*s)*10)/10,Qv=R(8,20,0.5),Lg=R(15,40,1),hg=R(8,25,1),lam=pick([0.02,0.03,0.05,0.1,0.15]),dpA=R(20000,70000,5000),pW=pick([2,3,4,5]);
  const A=Math.PI*di*di/4,v=Qv/3600/(A/1e6),dp=lam*Lg*1000*v*v/(di/1000*2),pv=dp/1e5+dpA/1e5,pp=pv+pW,h=pp*1e5/(1000*9.81)+hg;
  const ans=[{l:'Innendurchmesser',v:di,u:'mm',tol:0.001},{l:'Rohrquerschnitt',v:A,u:'mm²',tol:0.004},{l:'Strömungsgeschwindigkeit',v:v,u:'m/s',tol:0.005},{l:'Druckverlust der Rohrleitung',v:dp,u:'Pa',tol:0.008},{l:'Gesamtdruckverlust (Rohr + Armaturen)',v:pv,u:'bar',tol:0.008},{l:'Pumpendruck (mit Werkzeugdruck)',v:pp,u:'bar',tol:0.006},{l:'Gesamtförderhöhe',v:h,u:'m',tol:0.006}];
  return {text:`Bei der Rothaus Werkzeugmaschinen GmbH soll eine Kühlmittelpumpe ausgelegt werden. Sie fördert ${f(Qv,1)} m³/h Kühlwasser durch ein Stahlrohr ${f(da,1)} × ${s} mm (Länge ${Lg} m) zum Werkzeug; dort werden ${pW} bar Druck benötigt. Die geodätische Förderhöhe beträgt ${hg} m; Armaturen und Einbauten verursachen zusätzlich ${f(dpA,0)} Pa Druckverlust. Ermitteln Sie die benötigte Gesamtförderhöhe der Pumpe in Metern. Rohrreibungsverlust: Δp = λ · L · ρ · v² : (d_i · 2) mit λ = ${f(lam)}; ρ = 1.000 kg/m³, g = 9,81 m/s².`,
  given:[['Volumenstrom',f(Qv,1)+' m³/h'],['Rohr (Außen-Ø × Wanddicke)',`${f(da,1)} × ${s} mm`],['Leitungslänge',Lg+' m'],['geodätische Höhe',hg+' m'],['Rohrreibungszahl λ',f(lam)],['Zusatzverlust Armaturen',f(dpA,0)+' Pa'],['Druck am Werkzeug',pW+' bar']],ans,
  steps:[{l:'d_i',f:[`${f(da,1)} − 2 · ${s}`,f(di,1)+' mm']},{l:'A',f:['π · d_i² : 4',`π · ${f(di,1)}² : 4`,f(A)+' mm²']},{l:'v',f:[Q('Q','A'),Q(`${f(Qv,1)} m³ : 3600 s`,f(A/1e6,6)+' m²'),f(v)+' m/s']},{l:'Δp Rohr',f:['λ · L · ρ · v² : (d_i · 2)',`${f(lam)} · ${Lg} · 1000 · ${f(v)}² : (${f(di/1000,4)} · 2)`,f(dp,0)+' Pa = '+f(dp/1e5)+' bar']},{l:'Δp gesamt',f:['Rohr + Armaturen',`${f(dp/1e5)} + ${f(dpA/1e5)}`,f(pv)+' bar']},{l:'p Pumpe',f:['Δp gesamt + p Werkzeug',`${f(pv)} + ${pW}`,f(pp)+' bar']},{l:'H',f:['p : (ρ · g) + h_geo',`${f(pp*1e5,0)} Pa : (1000 · 9,81) + ${hg} m`,f(h)+' m']}],
  tip:'Förderhöhe = Druckhöhe + geodätische Höhe: 1 bar entspricht rund 10,2 m Wassersäule.'};}},

/* ───── Antriebsleistung beim Längsdrehen (F2023 T3c) ───── */
{id:'c_drehleistung',qs:'FT',title:'Schnittleistung und Antriebsleistung beim Längsdrehen (kc aus kc1.1 und mc)',gen(){
  const d0=pick([32,40,50]),d1=d0-R(8,14,1),au=1,ap=(d0-d1+au)/2,f_=pick([0.2,0.25,0.3,0.4]),kap=pick([80,90,95]),kc11=pick([1500,1740,1820,2000]),mc=pick([0.17,0.21,0.25,0.26,0.3]),vc=pick([90,100,110,130]),C1=1,C2=pick([1.2,1.3]),eta=pick([80,82,85]);
  const h=f_*Math.sin(kap*Math.PI/180),kc=kc11/Math.pow(h,mc),A=ap*h,Fc=kc*A*C1*C2,vs=vc/60,Pc=Fc*vs,P1=Pc/(eta/100)/1000;
  const ans=[{l:'Schnitttiefe ap',v:ap,u:'mm',tol:0.005},{l:'Spanungsdicke h',v:h,u:'mm',tol:0.005},{l:'spezifische Schnittkraft kc',v:kc,u:'N/mm²',tol:0.006},{l:'Spanungsquerschnitt A',v:A,u:'mm²',tol:0.006},{l:'Schnittkraft Fc',v:Fc,u:'N',tol:0.008},{l:'Schnittgeschwindigkeit',v:vs,u:'m/s',tol:0.004},{l:'Schnittleistung Pc',v:Pc/1000,u:'kW',tol:0.008},{l:'Antriebsleistung der Maschine',v:P1,u:'kW',tol:0.008}];
  return {text:`In der Dreherei der Ahlert Antriebstechnik GmbH wird eine Welle aus einem Rundstab Ø ${d0} mm vorgedreht: Das Wellenende wird auf Ø ${d1+au} mm (Aufmaß ${au} mm im Durchmesser für die Fertigbearbeitung) gedreht. Das Hartmetall-Werkzeug (mit Abstumpfung) hat einen Einstellwinkel κ = ${kap}°, der Vorschub beträgt f = ${f_} mm, der Maschinenwirkungsgrad ${eta} %. Berechnen Sie die maximal benötigte Antriebsleistung in kW (größte Schnitttiefe, h = f · sin κ). Tabellenwerte: kc1.1 = ${f(kc11,0)} N/mm², mc = ${f(mc)}, C1 = ${C1}, C2 = ${f(C2,1)}, vc = ${vc} m/min.`,
  given:[['Rohteil-Durchmesser',d0+' mm'],['Durchmesser nach Vorbearbeitung (inkl. Aufmaß)',(d1+au)+' mm'],['Vorschub f',f(f_)+' mm'],['Einstellwinkel κ',kap+'°'],['Wirkungsgrad Maschine',eta+' %'],['kc1.1',f(kc11,0)+' N/mm²'],['mc',f(mc)],['C1 / C2',`${C1} / ${f(C2,1)}`],['vc',vc+' m/min']],ans,
  steps:[{l:'ap',f:['(d₀ − d₁) : 2',`(${d0} − ${d1+au}) : 2`,f(ap)+' mm']},{l:'h',f:['f · sin κ',`${f(f_)} · sin ${kap}°`,f(h,3)+' mm']},{l:'kc',f:[Q('kc1.1','h^mc'),Q(f(kc11,0),`${f(h,3)}^${f(mc)}`),f(kc,1)+' N/mm²']},{l:'A',f:['ap · h',`${f(ap)} · ${f(h,3)}`,f(A,3)+' mm²']},{l:'Fc',f:['kc · A · C1 · C2',`${f(kc,1)} · ${f(A,3)} · ${C1} · ${f(C2,1)}`,f(Fc,1)+' N']},{l:'Pc',f:['Fc · vc',`${f(Fc,1)} N · ${f(vs,3)} m/s`,f(Pc,0)+' W']},{l:'P1',f:[Q('Pc','η'),Q(f(Pc,0)+' W',f(eta/100,2)),f(P1)+' kW']}],
  tip:'Beim Längsdrehen gilt h = f · sin κ und b = ap : sin κ. Die größte Schnitttiefe liegt an der Stelle mit dem größten Aufmaß.'};}}
);

CALC.push(
/* ───── Planfräsen: Antriebsleistung (kc aus kc1.1, Eingriffswinkel) und Hauptnutzungszeit (H2024 O7, H2022 T5) ───── */
{id:'c_fraesen_ext',qs:'FT',title:'Planfräsen: Antriebsleistung und Hauptnutzungszeit einer Platte',gen(){
  const d=pick([100,160,250,500,1000,1800]),ae=Math.round(d/pick([1.2,1.3,1.4,1.5])/10)*10,z=d<=160?pick([4,6,8]):d<=500?pick([8,12,36]):pick([90,120,180]),vc=pick([350,500,700,900]),fz=pick([0.1,0.12,0.14,0.2,0.23]),roh=pick([53,43,33,23]),fert=roh-pick([3,4,5,6]),ap=(roh-fert)/2,kc11=pick([830,1040,1270]),mc=pick([0.23,0.25,0.3]),C2=pick([1.2,1.3]),eta=pick([80,85,88]),l=R(800,3700,10),la=2,lu=2,i=2;
  const phi=2*Math.asin(ae/d)*180/Math.PI,kc=kc11/Math.pow(fz,mc),A=ap*fz,Fc=kc*A*1*C2,ze=z*phi/360,vs=vc/60,Pc=ze*Fc*vs,P1=Pc/(eta/100)/1000,n=vc*1000/(Math.PI*d),fv=fz*z,L=l+d+la+lu,th=L*i/(n*fv),ths=th*60;
  const ans=[{l:'Schnitttiefe ap je Seite',v:ap,u:'mm',tol:0.005},{l:'Eingriffswinkel φ',v:phi,u:'°',tol:0.01},{l:'spezifische Schnittkraft kc',v:kc,u:'N/mm²',tol:0.006},{l:'Schnittkraft je Schneide Fc',v:Fc,u:'N',tol:0.008},{l:'Anzahl der Schneiden im Eingriff ze',v:ze,u:'',tol:0.01},{l:'Schnittleistung Pc',v:Pc/1000,u:'kW',tol:0.01},{l:'Antriebsleistung der Maschine',v:P1,u:'kW',tol:0.01},{l:'Drehzahl n',v:n,u:'min⁻¹',tol:0.005},{l:'Vorschub je Umdrehung f',v:fv,u:'mm',tol:0.004},{l:'Vorschubweg L',v:L,u:'mm',tol:0.001},{l:'Hauptnutzungszeit je Platte',v:th,u:'min',tol:0.008},{l:'Hauptnutzungszeit je Platte',v:ths,u:'s',tol:0.008}];
  return {text:`In der Fräserei der Schuchardt Leichtmetall GmbH werden Platten beidseitig von ${roh} mm auf das Fertigmaß ${fert} mm geschlichtet (ap je Seite aus Roh- und Fertigmaß). Die Plattenbreite (Eingriffsbreite) beträgt ae = ${ae} mm, die Länge ${f(l,0)} mm. Es wird mit einem 90°-Planfräser Ø ${d} mm, z = ${z} Schneiden (Hartmetall, mit Abstumpfung) gefräst. Anlauf und Überlauf je ${la} mm; je Seite ein Schnitt (i = 2). a) Ermitteln Sie rechnerisch die benötigte Antriebsleistung der Fräsmaschine in kW (Eingriffswinkel φ = 2 · arcsin(ae : d) – für d : ae gleich Tabellenwert; ze = z · φ : 360°, nicht runden; Spanungsdicke h = fz). b) Berechnen Sie die Hauptnutzungszeit für die Bearbeitung einer Platte in Minuten und Sekunden (Vorschubweg L = l + d + la + lu).`,
  given:[['Fräser',`Ø ${d} mm · z = ${z}`],['Eingriffsbreite ae',ae+' mm'],['Roh-/Fertigmaß (Dicke)',`${roh} / ${fert} mm`],['Plattenlänge l',f(l,0)+' mm'],['vc',vc+' m/min'],['fz',f(fz)+' mm'],['kc1.1',kc11+' N/mm²'],['mc',f(mc)],['C1 / C2',`1,0 / ${f(C2,1)}`],['Wirkungsgrad Maschine',eta+' %']],ans,
  steps:[{h:'a) Antriebsleistung'},{l:'ap',f:['(Roh − Fertig) : 2',`(${roh} − ${fert}) : 2`,f(ap)+' mm']},{l:'φ',f:['2 · arcsin(ae : d)',`2 · arcsin(${ae} : ${d})`,f(phi)+'°']},{l:'kc',f:[Q('kc1.1','h^mc'),Q(kc11,`${f(fz)}^${f(mc)}`),f(kc,1)+' N/mm²']},{l:'Fc',f:['kc · ap · fz · C1 · C2',`${f(kc,1)} · ${f(ap)} · ${f(fz)} · 1,0 · ${f(C2,1)}`,f(Fc,1)+' N']},{l:'ze',f:['z · φ : 360°',`${z} · ${f(phi)}° : 360°`,f(ze,2)]},{l:'Pc',f:['ze · Fc · vc',`${f(ze,2)} · ${f(Fc,1)} N · ${f(vs,3)} m/s`,f(Pc,0)+' W']},{l:'P1',f:[Q('Pc','η'),Q(f(Pc,0)+' W',f(eta/100,2)),f(P1)+' kW']},
    {h:'b) Hauptnutzungszeit'},{l:'f',f:['fz · z',`${f(fz)} · ${z}`,f(fv,2)+' mm']},{l:'n',f:[Q('vc','π · d'),Q(vc+' m/min',`π · ${f(d/1000,3)} m`),f(n,2)+' min⁻¹']},{l:'L',f:['l + d + la + lu',`${f(l,0)} + ${d} + ${la} + ${lu}`,f(L,0)+' mm']},{l:'th',f:[Q('L · i','n · f'),Q(`${f(L,0)} · ${i}`,`${f(n,2)} · ${f(fv,2)}`),f(th)+' min = '+Math.floor(th)+' min '+f((th-Math.floor(th))*60,1)+' s']}],
  tip:'Beim Planfräsen mit großem Fräser sind meist mehrere Schneiden gleichzeitig im Eingriff: ze = z · φ : 360°. Der Vorschubweg enthält den Fräserdurchmesser, weil der Fräser zuerst vollständig über die Platte laufen muss.'};}},

/* ───── Beschleunigung und Verzögerung aus Zyklenzahl (H2023 T3) ───── */
{id:'c_beschl',qs:'MT',title:'Beschleunigung und Verzögerung aus Hubweg, Zykluszeit und Höchstgeschwindigkeit',gen(){
  let t;for(let k=0;k<300;k++){const v=pick([0.5,0.6,0.8,1.0]),s=pick([300,400,500,600])/1000,tr=pick([0.6,0.7,0.8,1.0]),n=pick([20,24,30]),kk=pick([2,3]);
    const T=60/n-tr,a=v*v*(1+1/kk)/(2*(v*T-s)),tb=v/a,tbr=v/(kk*a),tk=T-tb-tbr;if(v*T>s&&a>0.1&&a<8&&tk>=0.05){t={v,s,tr,n,kk,T,a,tb,tbr,tk};break}}
  const {v,s,tr,n,kk,T,a,tb,tbr,tk}=t;
  const ans=[{l:'Zeit für das Ausfahren',v:T,u:'s',tol:0.004},{l:'Beschleunigung a',v:a,u:'m/s²',tol:0.01},{l:'Verzögerung',v:kk*a,u:'m/s²',tol:0.01},{l:'Beschleunigungszeit',v:tb,u:'s',tol:0.01},{l:'Bremszeit',v:tbr,u:'s',tol:0.01},{l:'Zeit mit konstanter Geschwindigkeit',v:tk,u:'s',tol:0.015}];
  return {text:`Ein Pneumatikzylinder der Reuter Automation GmbH soll in einer Anlage ${n} Bewegungszyklen pro Minute ausführen. Die maximale Geschwindigkeit beträgt ${f(v,1)} m/s, der Arbeitshub (einmaliges Ausfahren) ${f(s*1000,0)} mm, der Rückhub (Einfahren) dauert ${f(tr,1)} s. Die Verzögerung ist ${kk}-mal so groß wie die Beschleunigung. Berechnen Sie die Beschleunigung und die Verzögerung des Zylinders beim Ausfahren (Ablauf: beschleunigen – mit v_max fahren – bremsen).`,
  given:[['Zyklen pro Minute',n],['v_max',f(v,1)+' m/s'],['Arbeitshub',f(s*1000,0)+' mm'],['Rückhubzeit',f(tr,1)+' s'],['Verhältnis Verzögerung : Beschleunigung',kk+' : 1']],ans,
  steps:[{l:'Zyklusdauer',f:[`60 s : ${n}`,f(60/n,2)+' s']},{l:'Ausfahrzeit',f:['t = Zyklus − Rückhub',`${f(60/n,2)} s − ${f(tr,1)} s`,f(T,2)+' s']},{h:'Weggleichung'},{t:`s = v·t − v²/(2a) − v²/(2·${kk}a) = v·t − ${f((1+1/kk)/2,3)}·v²/a`},{l:'a',f:[Q(`v² · (1 + 1/${kk})`,'2 · (v · t − s)'),Q(`${f(v*v,2)} · ${f(1+1/kk,3)}`,`2 · (${f(v,1)} · ${f(T,2)} − ${f(s,2)})`),f(a,3)+' m/s²']},{l:'Verzögerung',f:[`${kk} · a`,f(kk*a,3)+' m/s²']},{h:'Kontrolle der Zeiten'},{tab:[['Phase','Zeit'],['Beschleunigen v : a',f(tb,3)+' s'],['Bremsen v : (k·a)',f(tbr,3)+' s'],['konstante Fahrt',f(tk,3)+' s'],['Summe',f(T,2)+' s','s']]}],
  tip:'Der Weg im v-t-Diagramm ist die Trapezfläche: Gesamtzeit mal v_max minus die Dreiecke der Beschleunigungs- und Bremsphase.'};}},

/* ───── Passfeder-Auslegung (H2023 T6c) ───── */
{id:'c_passfeder',qs:'MT',title:'Passfeder auslegen: Drehmoment, Scherfläche, Länge und Normbezeichnung',gen(){
  const tabF=[[17,22,6,6],[22,30,8,7],[30,38,10,8],[38,44,12,8],[44,50,14,9]],row=pick(tabF),d=R(row[0]+1,row[1],1),b=row[2],h=row[3];
  const P=R(3000,15000,100),eta=pick([85,88,90,92]),n=pick([960,1450,2900]),Re=pick([360,430,490]),v=pick([4,6,8]),ser=[6,8,10,12,14,16,18,20,22,25,28,32,36,40,45,50,56,63,70,80,90,100,110,125];
  const w=2*Math.PI*n/60,M=P*eta/100/w,F=M/(d/2/1000),tz=0.6*Re/v,S=F/tz,l=S/b,ln=ser.find(x=>x>=l)||l;
  const ans=[{l:'Drehmoment an der Welle',v:M,u:'Nm',tol:0.006},{l:'Umfangskraft an der Welle',v:F,u:'N',tol:0.008},{l:'zulässige Scherspannung',v:tz,u:'N/mm²',tol:0.004},{l:'erforderliche Scherfläche',v:S,u:'mm²',tol:0.01},{l:'rechnerische Länge',v:l,u:'mm',tol:0.01},{l:'Passfederbreite b',v:b,u:'mm',tol:0.0001},{l:'Passfederhöhe h',v:h,u:'mm',tol:0.0001},{l:'Normlänge',v:ln,u:'mm',tol:0.0001}];
  return {text:`Ein Elektromotor der Kessler Antriebe GmbH gibt über eine Passfederverbindung Leistung auf eine Welle mit d = ${d} mm ab. Welle und Passfeder bestehen aus einem Werkstoff mit der Streckgrenze Re = ${Re} N/mm²; die Scherfestigkeit der Passfeder ist τ_aF = 0,6 · Re. Gefordert ist eine ${v}-fache Sicherheit. Bestimmen Sie die kleinstmögliche Passfeder (Querschnitt nach Tabellenbuch, Länge aus der Scherfläche S = b · l, Normlänge aufgerundet) und geben Sie sie normgerecht an (Form A).`,
  given:[['abgegebene Leistung (nach dem Motor)',f(P,0)+' W'],['Wirkungsgrad Motor',eta+' %'],['Drehzahl',f(n,0)+' min⁻¹'],['Wellendurchmesser',d+' mm'],['Streckgrenze Re',Re+' N/mm²'],['Sicherheit',v],['Passfederquerschnitt (Tabellenbuch, für d über '+row[0]+' bis '+row[1]+' mm)',`b × h = ${b} × ${h} mm`],['Normlängen (Auszug)',ser.slice(0,12).join(' · ')+' …']],ans,
  steps:[{l:'τ zul',f:['0,6 · Re : v',`0,6 · ${Re} : ${v}`,f(tz)+' N/mm²']},{l:'M',f:[Q('P · η','2 · π · n'),Q(`${f(P,0)} W · ${f(eta/100,2)}`,`2π · ${f(n/60,2)} s⁻¹`),f(M)+' Nm']},{l:'F',f:[Q('M','d : 2'),Q(f(M)+' Nm',`${f(d/2000,4)} m`),f(F,0)+' N']},{l:'S',f:[Q('F','τ zul'),Q(f(F,0)+' N',f(tz)+' N/mm²'),f(S)+' mm²']},{l:'l',f:[Q('S','b'),Q(f(S),b),f(l)+' mm → Normlänge '+ln+' mm']},{t:`Passfeder DIN 6885 – A – ${b} x ${h} x ${ln}`}],
  tip:'Die Passfeder wird auf Abscheren (Querkraft) und Flächenpressung bemessen; hier ist die Scherung maßgebend. Länge immer auf die nächste Normlänge aufrunden.'};}},

/* ───── Drehmomentschlüssel mit Vorsatzstück (F2024 O8) ───── */
{id:'c_drehmoment_vs',qs:'MT',title:'Drehmomentschlüssel mit Vorsatzstück: Umrechnungsfaktor und tatsächliches Anzugsmoment',gen(){
  const lw=R(250,350,1),lc=R(18,32,1),lx=lc-R(4,14,0.5),Mn=pick([100,120,150,170,200]),tol=pick([10,20,30]),Mm=Mn+tol/2,nS=R(30,80,1);
  const fk=(lw+lc)/(lw+lx),Mein=Mm*fk,Mist=Mm/fk,ok=Mist>=Mn&&Mist<=Mn+tol,dev=(Mist-Mm)/Mm*100;
  const ans=[{l:'Umrechnungsfaktor f',v:fk,u:'',tol:0.002},{l:'richtig einzustellendes Moment',v:Mein,u:'Nm',tol:0.003},{l:'tatsächlich erreichtes Moment (Einstellung auf Toleranzmitte)',v:Mist,u:'Nm',tol:0.004},{l:'Abweichung zur Toleranzmitte',v:dev,u:'%',tol:0.02,abs:0.05},{l:'Moment innerhalb der Toleranz? (1 = ja, 0 = nein)',v:ok?1:0,u:'',tol:0.0001,abs:0.01}];
  return {text:`In der Montage der Landwehr Aggregatebau GmbH werden ${nS} Schrauben eines Trägers mit ${Mn} Nm + ${tol} Nm angezogen (Zeichnungsangabe; einzustellen ist die Toleranzmitte). Der Drehmomentschlüssel (Wirklänge l_WSE = ${lw} mm) wurde mit einem Vorsatzstück mit dem Stichmaß l_CSE = ${f(lc,0)} mm kalibriert. Verwendet wurde ein Vorsatzstück mit l_xSE = ${f(lx,1)} mm, der Schlüssel wurde auf die Toleranzmitte eingestellt, alle Schrauben wurden als „i. O.“ dokumentiert. Umrechnungsfaktor: f = (l_WSE + l_CSE) : (l_WSE + l_xSE). Beurteilen Sie rechnerisch die Auswirkung des Fehlers und nennen Sie Maßnahmen.`,
  given:[['Zeichnungsangabe',`${Mn} Nm + ${tol} Nm`],['Wirklänge Schlüssel l_WSE',lw+' mm'],['Stichmaß Kalibrierung l_CSE',f(lc,0)+' mm'],['verwendetes Vorsatzstück l_xSE',f(lx,1)+' mm'],['Anzahl Schrauben',nS]],ans,
  steps:[{l:'f',f:[Q('l_WSE + l_CSE','l_WSE + l_xSE'),Q(`${lw} + ${f(lc,0)}`,`${lw} + ${f(lx,1)}`),f(fk,3)]},{l:'richtig einzustellen',f:['M · f',`${f(Mm,1)} Nm · ${f(fk,3)}`,f(Mein)+' Nm']},{l:'tatsächlich erreicht',f:[Q('M eingestellt','f'),Q(f(Mm,1)+' Nm',f(fk,3)),f(Mist)+' Nm']},{t:ok?`${f(Mist)} Nm liegt innerhalb der Toleranz ${Mn}–${Mn+tol} Nm: Nacharbeit nicht zwingend nötig. Nachziehen birgt Risiken (Setzverhalten, Haftreibung) – Entscheidung mit der Qualitätssicherung treffen und den Fehler dokumentieren.`:`${f(Mist)} Nm liegt außerhalb der Toleranz ${Mn}–${Mn+tol} Nm: Alle ${nS} Schrauben müssen mit richtig eingestelltem Moment geprüft bzw. nachgezogen werden; Fehler dokumentieren, Mitarbeiter in die Arbeitsanweisung einweisen.`}],
  tip:'Ein kürzeres Vorsatzstück als bei der Kalibrierung verkleinert den Hebel – das tatsächliche Moment ist dann kleiner (f > 1) bzw. größer (f < 1) als eingestellt.'};}}
);

CALC.push(
/* ───── Brennschneidzeit aus Zeichnungskontur (F2024 T4) ───── */
{id:'c_brennkontur',qs:'FT',title:'Brennschneidzeit: Konturlänge aus der Zeichnung (Schräge, Radien, Langlöcher)',gen(){
  const L=R(800,1000,20),B=R(400,500,20),dx=R(120,180,10),dy=R(40,80,10),Rr=R(40,70,10),b1=R(120,180,10),a1=R(240,360,20),nk=pick([2,4,6]),b2=R(24,40,2),a2=R(50,90,5),t=pick([10,20,30,40]),n=R(20,80,5),zg=pick([10,12,15,20]);
  const tv={10:0.55,20:0.45,30:0.38,40:0.33,50:0.29},v=tv[t];
  const sch=Math.hypot(dx,dy),links=B-2*dy,gerade=L-dx-Rr,rechts=B-2*Rr,bogen=Math.PI*Rr/2,U=links+2*sch+2*gerade+2*bogen+rechts;
  const Lg=2*a1+Math.PI*b1,Lk=nk*(2*a2+Math.PI*b2),Ges=U+Lg+Lk,tt=Ges/(v*1000),tz=tt*zg/100,T=(tt+tz)*n;
  const ans=[{l:'Länge der Schräge',v:sch,u:'mm',tol:0.003},{l:'Außenumfang der Platte',v:U,u:'mm',tol:0.004},{l:'Schnittlänge großes Langloch',v:Lg,u:'mm',tol:0.004},{l:'Schnittlänge aller kleinen Langlöcher',v:Lk,u:'mm',tol:0.004},{l:'gesamte Schnittlänge je Platte',v:Ges,u:'mm',tol:0.004},{l:'Schneidzeit je Platte',v:tt,u:'min',tol:0.005},{l:'Zugabe je Platte',v:tz,u:'min',tol:0.008},{l:'Auftragszeit für alle Platten',v:T,u:'min',tol:0.006}];
  const o={t:'Schneidgeschwindigkeit'};
  return {text:`In der Zuschnittabteilung der Hellwig Stahlbau GmbH sollen ${n} Trägerplatten aus S235JR (Blechdicke ${t} mm) mit dem Autogenbrenner (Acetylen, Qualitätsschnitt) geschnitten werden. Die Kontur ergibt sich aus der Zeichnung (Skizze); die Schräge ist aus den Maßen mit dem Satz des Pythagoras zu ermitteln, an den rechten Ecken sind Viertelkreise mit R ${Rr}. Entnehmen Sie die Schneidgeschwindigkeit der Tabelle (Auszug aus dem Tabellenbuch). Für Rüsten, Eilgangwege und Anschneiden der Schnittkanten ist eine Zugabe von ${zg} % auf die Schneidzeit zu berücksichtigen. Berechnen Sie die Brennschneidzeit für den gesamten Auftrag.`,
  given:[['Plattenmaße Länge × Breite',`${L} × ${B} mm`],['Schräge (links oben und unten)',`${dx} mm horizontal · ${dy} mm vertikal`],['Eckenradius rechts',`R ${Rr} mm`],['großes Langloch',`Breite ${b1} mm, Mittenabstand der Halbkreise ${a1} mm`],['kleine Langlöcher',`${nk} Stück, Breite ${b2} mm, Mittenabstand ${a2} mm`],['Blechdicke',t+' mm'],['Stückzahl',n],['Zugabe',zg+' %']],
  gtab:{head:['Blechdicke (mm)','10','20','30','40','50'],rows:[['Schneidgeschwindigkeit (m/min)','0,55','0,45','0,38','0,33','0,29']]},skd:{L,B,dx,dy,Rr,b1,a1,nk,b2,a2},ans,
  steps:[{h:'Konturlängen'},{l:'Schräge',f:['√(Δx² + Δy²)',`√(${dx}² + ${dy}²)`,f(sch)+' mm']},{tab:[['Element','Länge','Anzahl','Summe'],['linke Kante B − 2·Δy',f(links,0),1,f(links)],['Schräge',f(sch),2,f(2*sch)],['obere/untere Gerade L − Δx − R',f(gerade,0),2,f(2*gerade)],['Viertelkreis π·R : 2',f(bogen),2,f(2*bogen)],['rechte Kante B − 2·R',f(rechts,0),1,f(rechts)],['Außenumfang','','',f(U),'s'],['großes Langloch: 2·a + π·b',f(Lg),1,f(Lg)],['kleines Langloch: 2·a + π·b',f(2*a2+Math.PI*b2),nk,f(Lk)],['Gesamtschnittlänge','','',f(Ges),'s']]},
    {h:'Zeit'},{l:'Schneidzeit',f:[Q('L','v'),Q(f(Ges)+' mm',f(v*1000,0)+' mm/min'),f(tt)+' min je Platte']},{l:'Zugabe',f:[`${zg} %`,f(tz)+' min je Platte']},{l:'Auftragszeit',f:['(t + t_Zugabe) · n',`(${f(tt)} + ${f(tz)}) · ${n}`,f(T,1)+' min']}],
  tip:'Bei Langlöchern besteht die Kontur aus zwei Geraden (Mittenabstand) und zwei Halbkreisen (zusammen ein Vollkreis mit π · Breite).'};}}
);

CALC.push(
/* ───── Flexible Plankostenrechnung mit Abweichungsanalyse und anderem Beschäftigungsgrad (F2020 O1) ───── */
{id:'c_plan_abw',qs:'KW',title:'Flexible Plankostenrechnung: Abweichungsanalyse, Interpretation und Plankosten bei anderem Beschäftigungsgrad',gen(){
  const h1=R(2000,3000,100),h2=R(300,800,50),Bp=h1+h2,Kp=R(300000,600000,5000),fx=pick([30,40,50]),mehr=pick([-1,1])*R(150,500,10),Bi=Bp+mehr,pg=pick([85,90,95,105]);
  const Kf=Kp*fx/100,Kv=Kp-Kf,verr=Kp/Bp*Bi,soll=Kf+Kv/Bp*Bi,Ist=Math.round(soll*(1+R(-20,30,1)/1000)/10)*10,BA=verr-soll,VA=soll-Ist,Kj=Kf+pg/100*Kv;
  const ans=[{l:'verrechnete Plankosten',v:verr,u:'€',tol:0.002},{l:'Sollkosten',v:soll,u:'€',tol:0.002},{l:'Beschäftigungsabweichung (verr. Plankosten − Sollkosten)',v:BA,u:'€',tol:0.006,abs:2},{l:'Verbrauchsabweichung (Sollkosten − Istkosten)',v:VA,u:'€',tol:0.006,abs:2},{l:'Plankostenansatz bei '+pg+' % Beschäftigung',v:Kj,u:'€',tol:0.002}];
  return {text:`Für die Kostenstelle Instandhaltung der Ehrlich Windtechnik GmbH hat das Controlling die Gemeinkosten für den Monat März geplant. Bezugsgröße sind die Mitarbeiterstunden für Reparatur und Wartung: ${f(h1,0)} h aus bestehenden Verträgen und ${f(h2,0)} h für ungeplante Reparaturen. Die Plankosten betragen ${e(Kp)}, der Fixkostenanteil ${fx} %. Anfang April meldet das Controlling ${f(Math.abs(mehr),0)} ${mehr>0?'Mehrstunden':'Minderstunden'} gegenüber der Planung; die Istkosten betragen ${e(Ist)}. a) Führen Sie eine Abweichungsanalyse durch: 1. Beschäftigungsabweichung, 2. Verbrauchsabweichung. b) Interpretieren Sie die ermittelte Beschäftigungsabweichung. c) Für einen späteren Monat wird mit einem Beschäftigungsgrad von ${pg} % geplant. Ermitteln Sie den Plankostenansatz bei unveränderten Faktorpreisen.`,
  given:[['Planbeschäftigung',f(Bp,0)+' h ('+f(h1,0)+' + '+f(h2,0)+')'],['Plankosten',e(Kp)],['Fixkostenanteil',fx+' %'],['Istbeschäftigung',f(Bi,0)+' h'],['Istkosten',e(Ist)]],ans,
  steps:[{l:'verr. Plankosten',f:[Q('Plankosten','Planbeschäftigung')+' · Istbeschäftigung',Q(e(Kp),f(Bp,0)+' h')+` · ${f(Bi,0)} h`,e(verr)]},{l:'Sollkosten',f:['Kf + Kv : Bp · Bi',`${e(Kf)} + ${Q(e(Kv),f(Bp,0)+' h')} · ${f(Bi,0)} h`,e(soll)]},{l:'Beschäftigungsabw.',f:['verr. Plankosten − Sollkosten',`${e(verr)} − ${e(soll)}`,(BA>=0?'+':'−')+e(Math.abs(BA))]},{l:'Verbrauchsabw.',f:['Sollkosten − Istkosten',`${e(soll)} − ${e(Ist)}`,(VA>=0?'+ ':'− ')+e(Math.abs(VA))]},
    {h:'b) Interpretation'},{t:BA>=0?'Die Beschäftigungsabweichung ist positiv, weil die Istbeschäftigung über der Planbeschäftigung liegt (Überbeschäftigung). Es wurden mehr Fixkosten verrechnet als angefallen sind: Fixkostenüberdeckung.':'Die Beschäftigungsabweichung ist negativ, weil die Istbeschäftigung unter der Planbeschäftigung liegt (Unterbeschäftigung). Es konnten nicht alle Fixkosten verrechnet werden: Fixkostenunterdeckung (Leerkosten).'},{t:VA>=0?'Die Verbrauchsabweichung ist positiv: Es wurde sparsamer gewirtschaftet als geplant.':'Die Verbrauchsabweichung ist negativ: Die Istkosten liegen über den Sollkosten (Mehrverbrauch, Preisabweichungen).'},
    {h:'c) Plankostenansatz'},{l:'Plankosten',f:['Kf + Beschäftigungsgrad · Kv',`${e(Kf)} + ${f(pg/100,2)} · ${e(Kv)}`,e(Kj)]}],
  tip:'Die Beschäftigungsabweichung entsteht nur durch die Fixkosten; bei Istbeschäftigung über Plan ist sie positiv (Überdeckung), darunter negativ (Unterdeckung).'};}},

/* ───── Break-even-Umsatz mit Szenario (F2020 O6) ───── */
{id:'c_beumsatz_ext',qs:'KW',title:'Break-even-Umsatz, Betriebsergebnis und Szenario mit prozentualer Veränderung',gen(){
  const x=R(6000,9000,100),p=R(150,200,5),lo=R(30,40,1),pnk=R(70,90,5),gk=R(700000,950000,1000),gv=Math.round(gk*R(35,50,1)/100/1000)*1000,q=pick([45,50,55]),dF=R(20000,45000,1000);
  const kv=lo+lo*pnk/100+gv/x,db=p-kv,Kf=gk-gv,xb=Kf/db,ub=p*xb,BE=db*x-Kf;
  const kv2=p*q/100,db2=p-kv2,Kf2=Kf+dF,xb2=Kf2/db2,ub2=p*xb2,BE2=db2*x-Kf2,ch=(BE2-BE)/Math.abs(BE)*100;
  const ans=[{l:'variable Kosten je Stunde',v:kv,u:'€/h',tol:0.003},{l:'Deckungsbeitrag je Stunde',v:db,u:'€/h',tol:0.004},{l:'Fixkosten je Quartal',v:Kf,u:'€',tol:0.001},{l:'Break-even-Menge',v:xb,u:'h',tol:0.004},{l:'Break-even-Umsatz',v:ub,u:'€',tol:0.004},{l:'geplantes Betriebsergebnis',v:BE,u:'€',tol:0.006,abs:5},{l:'Szenario: Break-even-Umsatz',v:ub2,u:'€',tol:0.004},{l:'Szenario: Betriebsergebnis',v:BE2,u:'€',tol:0.006,abs:5},{l:'Veränderung des Betriebsergebnisses',v:ch,u:'%',tol:0.01,abs:0.05}];
  return {text:`Die Ehrlich Windtechnik GmbH plant für das dritte Quartal ${f(x,0)} Mitarbeiterstunden Fremdwartung zu einem Durchschnittserlös von ${f(p,0)} € je Stunde. Stundenlohn Wartungspersonal ${e(lo)}, Personalnebenkosten ${pnk} % (variabel), Gemeinkosten ${e(gk)}, davon ${e(gv)} variabel. a) Berechnen Sie den Break-even-Umsatz für das Quartal. b) Ermitteln Sie das geplante Betriebsergebnis. c) Die Geschäftsleitung will die variablen Kosten durch Prozessoptimierung auf ${q} % des Umsatzerlöses begrenzen; die Maßnahmen erhöhen die Fixkosten um ${e(dF)} im Quartal. Ermitteln Sie für diesen Fall den Break-even-Umsatz, das voraussichtliche Betriebsergebnis bei unveränderten Stunden und die prozentuale Veränderung des Betriebsergebnisses.`,
  given:[['geplante Stunden',f(x,0)+' h'],['Erlös je Stunde',e(p)],['Stundenlohn',e(lo)],['Personalnebenkosten',pnk+' %'],['Gemeinkosten gesamt / variabel',`${e(gk)} / ${e(gv)}`]],ans,
  steps:[{h:'a) Ausgangslage'},{l:'kv',f:['Lohn + PNK + variable GK : Stunden',`${f(lo)} + ${f(lo*pnk/100)} + ${Q(e(gv),f(x,0)+' h')}`,f(kv)+' €/h']},{l:'db',f:['p − kv',`${f(p)} − ${f(kv)}`,f(db)+' €/h']},{l:'Kf',f:['Gemeinkosten − variable GK',`${e(gk)} − ${e(gv)}`,e(Kf)]},{l:'xBEP',f:[Q('Kf','db'),Q(e(Kf),f(db)+' €/h'),f(xb)+' h']},{l:'UBEP',f:['p · xBEP',`${f(p)} · ${f(xb)}`,e(ub)]},{h:'b) Betriebsergebnis'},{l:'BE',f:['db · x − Kf',`${f(db)} · ${f(x,0)} − ${e(Kf)}`,e(BE)]},
    {h:'c) Szenario'},{l:'kv neu',f:[`${q} % · ${f(p)}`,f(kv2)+' €/h']},{l:'db neu',f:[`${f(p)} − ${f(kv2)}`,f(db2)+' €/h']},{l:'Kf neu',f:[`${e(Kf)} + ${e(dF)}`,e(Kf2)]},{l:'xBEP neu',f:[Q('Kf neu','db neu'),Q(e(Kf2),f(db2)),f(xb2)+' h']},{l:'UBEP neu',f:[`${f(p)} · ${f(xb2)}`,e(ub2)]},{l:'BE neu',f:[`${f(db2)} · ${f(x,0)} − ${e(Kf2)}`,e(BE2)]},{l:'Veränderung',f:[Q('BE neu − BE alt','BE alt')+' · 100 %',Q(`${e(BE2)} − ${e(BE)}`,e(BE))+' · 100 %',(ch>=0?'+':'')+f(ch)+' %']}],
  tip:'Beim Break-even gilt: Umsatz = Menge · Preis. Ändern sich variable Kosten als Anteil am Umsatz, wird der Deckungsbeitrag je Stunde p − Anteil · p.'};}},

/* ───── Mehrstufige Divisionskalkulation mit Lagerbestandsveränderungen (F2021 T5) ───── */
{id:'c_divkalk',qs:'KW',title:'Mehrstufige Divisionskalkulation mit Pufferlagern (Losgrößen rückwärts)',gen(){
  const M4=R(250,400,10),sg=[pick([-1,1]),pick([-1,1]),pick([-1,1])],dv=[R(20,90,10),R(20,90,10),R(20,90,10)];
  // C zwischen AS3 und AS4, B zwischen AS2 und AS3, A zwischen AS1 und AS2; Mehrbestand = +, Minderbestand = −
  const bC=sg[2]*dv[2],bB=sg[1]*dv[1],bA=sg[0]*dv[0],L4=M4,L3=L4+bC,L2=L3+bB,L1=L2+bA,lots=[L1,L2,L3,L4];
  const mat=[R(8,15,0.5),R(20,35,0.5),R(6,12,0.5),R(25,40,0.5)],tot=lots.map(l=>Math.round(l*R(35,85,5)/100)*100),each=tot.map((t,i)=>t/lots[i]),st=each.map((c,i)=>c+mat[i]),HK=sum_(st);
  const ans=[];lots.forEach((l,i)=>ans.push({l:`Losgröße Arbeitsschritt ${i+1}`,v:l,u:'Stück',tol:0.0001,abs:0.5}));each.forEach((c,i)=>ans.push({l:`Lohn-/Gemeinkosten je Stück AS ${i+1}`,v:c,u:'€',tol:0.004}));st.forEach((c,i)=>ans.push({l:`Stückkosten AS ${i+1} (mit Material)`,v:c,u:'€',tol:0.004}));ans.push({l:'Herstellkosten je Antriebseinheit',v:HK,u:'€',tol:0.003});
  const bt=(b)=>b>=0?`Mehrbestand ${b} Stück`:`Minderbestand ${-b} Stück`;
  return {text:`In der Montage der Harmsen Getriebe GmbH durchläuft die Baugruppe Antriebseinheit vier Arbeitsschritte mit Pufferlagern dazwischen: AS 1 → Lager A → AS 2 → Lager B → AS 3 → Lager C → AS 4. Im Abrechnungsmonat wurden ${M4} Antriebseinheiten in AS 4 fertiggestellt. Bestandsveränderungen der Lager zum Monatsende: Lager A ${bt(bA)}, Lager B ${bt(bB)}, Lager C ${bt(bC)}. Berechnen Sie die Herstellkosten für eine Antriebseinheit (mehrstufige Divisionskalkulation: zuerst die Losgrößen der Arbeitsschritte bestimmen, Material je Stück ist stufenweise hinzuzurechnen).`,
  given:[['Fertiggestellt in AS 4',M4+' Stück']],gtab:{head:['Arbeitsschritt','1','2','3','4'],rows:[['Materialkosten je Stück (€)',...mat.map(x=>f(x))],['Lohn- und Gemeinkosten des Arbeitsschritts (€)',...tot.map(x=>f(x,0))]]},ans,
  steps:[{h:'Losgrößen (von hinten nach vorn)'},{t:'Mehrbestand im Lager: Es wurde mehr hineingelegt als entnommen – die vorherige Stufe hat mehr gefertigt. Minderbestand: Es wurde aus dem Lager entnommen – die vorherige Stufe hat weniger gefertigt.'},{tab:[['Stufe','Rechnung','Losgröße'],['AS 4','',L4],['AS 3',`${L4} ${bC>=0?'+':'−'} ${Math.abs(bC)} (Lager C)`,L3],['AS 2',`${L3} ${bB>=0?'+':'−'} ${Math.abs(bB)} (Lager B)`,L2],['AS 1',`${L2} ${bA>=0?'+':'−'} ${Math.abs(bA)} (Lager A)`,L1]]},
    {h:'Stückkosten je Stufe'},{tab:[['Stufe','Lohn/GK je Stück','Material','Summe'],...lots.map((l,i)=>[`AS ${i+1}`,`${f(tot[i],0)} : ${l} = ${f(each[i])}`,f(mat[i]),f(st[i])]),['Herstellkosten','','',e(HK),'s']]}],
  tip:'Jede Stufe wird durch ihre eigene Losgröße geteilt, nicht durch die Endmenge – Pufferlager verändern die Stückzahlen zwischen den Stufen.'};}},

/* ───── Kostenvergleich Nassbearbeitung / MMS mit Amortisation (F2021 O2) ───── */
{id:'c_kss_amort',qs:'KW',title:'Kostenvergleich Nassbearbeitung und Minimalmengenschmierung mit Amortisationsdauer',gen(){
  const wo=52,V=R(5000,9000,500),cp=pick([2,3,4]),pk=R(6,9,0.5),h8=pick([1,1.5,2]),tank=pick([800,1000,1200]),pe=R(0.35,0.6,0.01),ha=R(12,20,1),lo=R(26,32,0.2),red=pick([85,90,95]),po=R(7,10,0.5),hw=pick([1,2,3]),sp=R(2000,3000,100),hi=pick([3,4,5]),li=R(28,34,0.2),nd=pick([4,5,6]),zi=pick([6,8,10]);
  const kss=V*cp/100*pk,pp=h8*lo*wo/8,ent=tank*pe,pe2=ha*lo,N=kss+pp+ent+pe2;
  const AK=sp+hi*li,afa=AK/nd,zs=AK/2*zi/100,k2=V*cp/100*(1-red/100)*po,w2=hw*lo,M=afa+zs+k2+w2,sav=N-M,rf=sav+afa,ta=AK/rf;
  const ans=[{l:'Nass: Kosten Kühlschmierstoff',v:kss,u:'€',tol:0.003},{l:'Nass: Personalkosten Prüfung/Wartung',v:pp,u:'€',tol:0.004},{l:'Nass: Entsorgungskosten',v:ent,u:'€',tol:0.003},{l:'Nass: Personalkosten Entsorgung',v:pe2,u:'€',tol:0.003},{l:'Nass: Gesamtkosten je Jahr',v:N,u:'€',tol:0.003},{l:'MMS: Anschaffungskosten inkl. Installation',v:AK,u:'€',tol:0.003},{l:'MMS: kalk. Abschreibung je Jahr',v:afa,u:'€',tol:0.003},{l:'MMS: kalk. Zinsen je Jahr',v:zs,u:'€',tol:0.004},{l:'MMS: Kosten MMS-Öl',v:k2,u:'€',tol:0.005},{l:'MMS: Personalkosten Wartung',v:w2,u:'€',tol:0.003},{l:'MMS: Gesamtkosten je Jahr',v:M,u:'€',tol:0.003},{l:'jährlicher Rückfluss (Ersparnis + Abschreibung)',v:rf,u:'€',tol:0.004},{l:'Amortisationsdauer',v:ta,u:'Jahre',tol:0.008,abs:0.02}];
  return {text:`In der Zerspanung der Lindemann Präzisionsteile GmbH soll geprüft werden, ob je Bearbeitungszentrum (BAZ) von Nassbearbeitung auf Minimalmengenschmierung (MMS) umgestellt wird (Betrieb ${wo} Wochen im Jahr). Nassbearbeitung: ${f(V,0)} l Kühlschmierstoff-Gemisch/Jahr, Konzentratanteil ${cp} %, Konzentrat ${e(pk)}/l; wöchentliche Prüfung/Wartung ${f(h8,1)} h für 8 BAZ; einmal jährlich wird der komplette Maschinentank (${f(tank,0)} l) entsorgt (${e(pe)}/l); Entsorgungsaufwand (Demontage, Reinigung, Montage, Befüllung) ${f(ha,0)} h je BAZ. Facharbeiter ${e(lo)}/h. MMS: Konzentratverbrauch −${red} %, MMS-Öl ${e(po)}/l, keine Entsorgungskosten, Wartung ${hw} h pro Jahr je BAZ; Sprühsystem ${e(sp)} je BAZ, Installation ${hi} h durch die Instandhaltung (${e(li)}/h); Nutzungsdauer ${nd} Jahre, kalkulatorischer Zinssatz ${zi} % (auf das halbe Anlagekapital). a) Ermitteln Sie die jährlichen Kosten je BAZ für beide Verfahren. b) Ermitteln Sie die Amortisationsdauer der Umstellung auf MMS (Rückfluss = jährliche Kostenersparnis + Abschreibung).`,
  given:[],ans,
  steps:[{h:'a) Nassbearbeitung'},{tab:[['Kostenart','Rechnung','€/Jahr'],['Kühlschmierstoff',`${f(V,0)} l · ${cp} % · ${f(pk)}`,f(kss)],['Prüfung/Wartung',`${f(h8,1)} h · ${f(lo)} · ${wo} : 8`,f(pp)],['Entsorgung Tankinhalt',`${f(tank,0)} l · ${f(pe)}`,f(ent)],['Personal Entsorgung',`${f(ha,0)} h · ${f(lo)}`,f(pe2)],['Gesamt','',f(N),'s']]},
    {h:'MMS'},{tab:[['Kostenart','Rechnung','€/Jahr'],['Anschaffung inkl. Installation',`${f(sp,0)} + ${hi} h · ${f(li)}`,f(AK)],['Abschreibung',`${f(AK)} : ${nd}`,f(afa)],['Zinsen',`${f(AK)} : 2 · ${zi} %`,f(zs)],['MMS-Öl',`${f(V*cp/100)} l · ${f(1-red/100,2)} · ${f(po)}`,f(k2)],['Wartung',`${hw} h · ${f(lo)}`,f(w2)],['Gesamt','',f(M),'s']]},
    {h:'b) Amortisation'},{l:'Ersparnis',f:[`${f(N)} − ${f(M)}`,e(sav)+'/Jahr']},{l:'Rückfluss',f:['Ersparnis + Abschreibung',`${f(sav)} + ${f(afa)}`,e(rf)]},{l:'Amortisationsdauer',f:[Q('Anschaffungskosten','Rückfluss'),Q(e(AK),e(rf)),f(ta)+' Jahre']}],
  tip:'Bei der Kostenvergleichs-Amortisation ist der Rückfluss die jährliche Kosteneinsparung plus Abschreibung (kein Gewinn vorhanden).'};}}
);

CALC.push(
/* ───── Netzplan aus ungeordneter Vorgangsliste (F2021 O5) ───── */
{id:'c_netzplan_vl',qs:'PS',title:'Netzplan aus ungeordneter Vorgangsliste: Vorgänger/Nachfolger, Zeiten, kritischer Weg, Verzögerung',gen(){
  const nm=['Projektplanung','Angebote Hardware einholen und Anbieter auswählen','Angebote Software einholen und Anbieter auswählen','Hardware beschaffen','Software auf Testrechner installieren','Leitstand einrichten','Hardware am Prüfstand installieren','Software auf Testrechner modifizieren','Verkabelung Leitstand und Prüfstand','gesamte Anlage testen','Freigabe der Anlage'];
  const pre=[[],[0],[0],[1],[2],[3],[3],[4],[5,6],[7,8],[9]],n=11,du=[R(2,5,1),R(3,6,1),R(4,8,1),R(1,3,1),R(1,2,1),R(1,3,1),R(3,6,1),R(2,4,1),R(1,3,1),R(1,3,1),1];
  const suc=nm.map((_,i)=>pre.map((p,k)=>p.includes(i)?k:-1).filter(k=>k>=0));
  const calc=(d)=>{const FAZ=[],FEZ=[],SAZ=[],SEZ=[];for(let i=0;i<n;i++){FAZ[i]=Math.max(0,...pre[i].map(p=>FEZ[p]));FEZ[i]=FAZ[i]+d[i]}const end=Math.max(...FEZ);for(let i=n-1;i>=0;i--){SEZ[i]=suc[i].length?Math.min(...suc[i].map(k=>SAZ[k])):end;SAZ[i]=SEZ[i]-d[i]}return {FAZ,FEZ,SAZ,SEZ,end,GP:SAZ.map((s,i)=>s-FAZ[i])}};
  const A=calc(du),dly=A.GP[5]+R(1,3,1),du2=du.slice();du2[5]+=dly;const B=calc(du2);
  const ord=[...Array(n).keys()].sort(()=>Math.random()-0.5);
  const ans=[];
  ord.forEach(i=>{ans.push({l:`Anzahl Vorgänger „${nm[i]}“`,v:pre[i].length,u:'',tol:0,abs:0.01});ans.push({l:`Anzahl Nachfolger „${nm[i]}“`,v:suc[i].length,u:'',tol:0,abs:0.01})});
  const base=ans.length;
  nm.forEach((_,i)=>['FAZ','FEZ','SAZ','SEZ','GP'].forEach(k=>ans.push({l:`${k} Vorgang ${i+1}`,v:A[k][i],u:'',tol:0,abs:0.01})));
  const cb=ans.length;
  ans.push({l:'Projektdauer ohne Verzögerung',v:A.end,u:'Tage',tol:0,abs:0.01},{l:'Anzahl kritischer Vorgänge',v:A.GP.filter(x=>x===0).length,u:'',tol:0,abs:0.01},{l:'Projektdauer mit Verzögerung',v:B.end,u:'Tage',tol:0,abs:0.01},{l:'Gesamtpuffer „Hardware am Prüfstand installieren“ (Vorgang 7) nach Verzögerung',v:B.GP[6],u:'Tage',tol:0,abs:0.01},{l:'Anzahl kritischer Vorgänge nach Verzögerung',v:B.GP.filter(x=>x===0).length,u:'',tol:0,abs:0.01});
  const crit=A.GP.map((g,i)=>g===0?i+1:null).filter(x=>x),crit2=B.GP.map((g,i)=>g===0?i+1:null).filter(x=>x);
  return {text:`Die Harmsen Getriebe GmbH digitalisiert die Überwachung ihres Prüffelds. Die Vorgänge des Projekts „Leitstand Prüffeld“ liegen nicht in zeitlicher Reihenfolge vor (Anlage 1). a) Bestimmen Sie für jeden Vorgang die Anzahl der unmittelbaren Vorgänger und Nachfolger (Anlage 1) und ordnen Sie die Vorgänge dabei sachlogisch (Planung vor Angeboten, Angebote vor Beschaffung bzw. Installation, Test erst nach Installation und Verkabelung, Freigabe zuletzt). b) Übertragen Sie die Vorgänge in die chronologische Vorgangsliste (Anlage 2) und ermitteln Sie FAZ, FEZ, SAZ, SEZ und Gesamtpuffer. Projektbeginn = 0. Kennzeichnen Sie den kritischen Weg. c) Der Vorgang „Leitstand einrichten“ (Nr. 6) verzögert sich um ${dly} Tage. Welche Auswirkung hat das auf Projektdauer und kritischen Weg?`,
  given:[],
  anlage:[{nr:'Anlage 1',title:'Vorgangsliste (ungeordnet)',note:'Unmittelbare Vorgänger bzw. Nachfolger zählen.',head:['Vorgang','Dauer (Tage)','Anzahl Vorgänger','Anzahl Nachfolger'],rows:ord.map((i,k)=>[nm[i],du[i],{a:2*k},{a:2*k+1}])},
   {nr:'Anlage 2',title:'Chronologische Vorgangsliste mit Zeiten',note:'Reihenfolge der Nummern wie sie sich aus der Logik von Anlage 1 ergibt (Nr. 1 = Projektplanung, Nr. 11 = Freigabe).',head:['Nr.','Vorgang','Dauer','FAZ','FEZ','SAZ','SEZ','GP'],rows:nm.map((x,i)=>[String(i+1),x,du[i],...[0,1,2,3,4].map(j=>({a:base+i*5+j}))])},
   {nr:'Anlage 3',title:'Auswirkung der Verzögerung (Vorgang 6 +'+dly+' Tage)',head:['Größe','Wert'],rows:[['Projektdauer ohne Verzögerung (Tage)',{a:cb}],['Anzahl kritischer Vorgänge ohne Verzögerung',{a:cb+1}],['Projektdauer mit Verzögerung (Tage)',{a:cb+2}],['Gesamtpuffer Vorgang 7 nach Verzögerung (Tage)',{a:cb+3}],['Anzahl kritischer Vorgänge nach Verzögerung',{a:cb+4}]]}],
  ans,
  steps:[{h:'a) Vorgänger/Nachfolger'},{tab:[['Nr.','Vorgang','Dauer','Vorgänger','Nachfolger'],...nm.map((x,i)=>[i+1,x,du[i],pre[i].map(p=>p+1).join(', ')||'–',suc[i].map(p=>p+1).join(', ')||'–'])],head:true},
   {h:'b) Zeiten'},{tab:[['Nr.','Dauer','FAZ','FEZ','SAZ','SEZ','GP'],...nm.map((x,i)=>[i+1,du[i],A.FAZ[i],A.FEZ[i],A.SAZ[i],A.SEZ[i],A.GP[i]])],head:true},{l:'FAZ',f:['größter FEZ der Vorgänger']},{l:'SEZ',f:['kleinster SAZ der Nachfolger']},{l:'GP',f:['SAZ − FAZ']},{t:`Projektdauer ${A.end} Tage; kritischer Weg (GP = 0): ${crit.join(' → ')}.`},
   {h:'c) Verzögerung'},{t:`Vorgang 6 hat ${A.GP[5]} Tage Puffer und verzögert sich um ${dly} Tage. ${dly-A.GP[5]} Tag(e) liegen über dem Puffer: Die Projektdauer steigt von ${A.end} auf ${B.end} Tage. Neuer kritischer Weg: ${crit2.join(' → ')}. Vorgang 7 hat danach ${B.GP[6]} Tage Puffer.`}],
  tip:'Vorwärtsrechnung: FAZ = größter FEZ der Vorgänger. Rückwärtsrechnung: SEZ = kleinster SAZ der Nachfolger. Kritisch = GP 0.'};}}
);

